import { expect, type Download, type Page, test } from "@playwright/test";
import { readFile } from "node:fs/promises";

import * as ui from "@e2e/ui-actions";

export const openDownloadPopoverAndAssert = async (page: Page) => {
  await test.step("Open download popover", async () => {
    await ui.downloads.actions(page).openPopover();
  });

  await test.step("Assert download options visible", async () => {
    await ui.downloads.assertions(page).popoverIsVisible();
  });
};

export const downloadE2eFile = async (page: Page): Promise<Download> => {
  return test.step("Download E2E test file", async () => {
    const downloadPromise = page.waitForEvent("download");
    await ui.downloads.actions(page).clickE2eOption();
    return downloadPromise;
  });
};

export const downloadTrackerLogsFile = async (page: Page): Promise<Download> => {
  return test.step("Download tracker logs file", async () => {
    const downloadPromise = page.waitForEvent("download");
    await ui.downloads.actions(page).clickTrackerLogsOption();
    return downloadPromise;
  });
};

export const readDownloadedText = async (download: Download): Promise<string> => {
  const path = await download.path();
  if (!path) {
    throw new Error("Downloaded file path was not available");
  }
  return readFile(path, "utf-8");
};

export const downloadTrackerLogsAndAssertContent = async (page: Page, expectedTexts: string[]) => {
  await flowsOpenPopover(page);
  const download = await downloadTrackerLogsFile(page);
  const content = await readDownloadedText(download);

  await test.step("Assert downloaded tracker logs JSON contains expected messages", () => {
    for (const text of expectedTexts) {
      expect(content, `Tracker logs JSON should contain "${text}"`).toContain(text);
    }
  });
};

export const downloadE2eYamlAndAssertContent = async (page: Page, expectedTexts: string[]) => {
  await flowsOpenPopover(page);
  const download = await downloadE2eFile(page);
  const content = await readDownloadedText(download);

  await test.step("Assert downloaded E2E YAML contains expected flow steps", () => {
    for (const text of expectedTexts) {
      expect(content, `E2E YAML should contain "${text}"`).toContain(text);
    }
  });
};

const flowsOpenPopover = async (page: Page) => {
  await openDownloadPopoverAndAssert(page);
};
